import { useState } from "react";
import type { ReactElement } from "react";
import "./Component.css";

export type Props = {
  initialValue: number;
  step: number;
  onChange: (value: number) => void;
};

export function Component({ initialValue, step, onChange }: Props): ReactElement {
  const [baseline] = useState<number>(initialValue);
  const [value, setValue] = useState<number>(initialValue);
  const isAtBaseline: boolean = value === baseline;

  function changeBy(delta: number): void {
    const nextValue: number = value + delta;
    setValue(nextValue);
    onChange(nextValue);
  }

  function reset(): void {
    if (value === baseline) return;
    setValue(baseline);
    onChange(baseline);
  }

  return (
    <div data-testid="panel" className="weighted-counter-panel">
      <output aria-label="Value">{value}</output>
      <button type="button" onClick={() => changeBy(step)}>Add</button>
      <button type="button" onClick={() => changeBy(-step)}>Subtract</button>
      <button type="button" onClick={reset} disabled={isAtBaseline}>
        Reset
      </button>
    </div>
  );
}

